# region: shape
def shape(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: emit
def emit(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(digest(intake(emit(shape(raw)))))

